from collections import deque

def successors(s, fixed=False):
    stock, holds = s
    if (stock > holds if fixed else stock > 0):
        yield 'Reserve', (stock, holds + 1)
    if holds > 0:
        yield 'Commit', (stock - 1, holds - 1)

queue = deque([((1, 0), [])])
seen = {(1, 0)}
while queue:
    state, trace = queue.popleft()
    if state[0] < 0:
        print('Original: shortest Safety violation:', [((1, 0), 'Init')] + trace)
        break
    if len(trace) < 6:
        for action, target in successors(state):
            if target not in seen:
                seen.add(target)
                queue.append((target, trace + [(target, action)]))
for initial in range(6):
    queue = deque([(initial, 0)])
    seen = {(initial, 0)}
    deadlocks = set()
    while queue:
        state = queue.popleft()
        assert 0 <= state[1] <= state[0] <= initial
        targets = list(successors(state, True))
        if not targets:
            deadlocks.add(state)
        for action, target in targets:
            if target not in seen:
                seen.add(target)
                queue.append(target)
    print(f'Proposed guard, initial={initial}: {len(seen)} reachable states; invariant holds; terminal states={sorted(deadlocks)}')
